const { query, sort, maxResults } = $.input;
if (!query) throw new Error('query is required');
const params = {
  q: query,
  per_page: String(Math.max(1, Math.min(30, maxResults || 5)))
};
if (sort && sort !== 'best-match') params.sort = sort;
return { params };

const resp = $.steps.searchRepos.response || {};
const items = resp.items || [];
const fetchCount = $.input.includeCommits ? items.length : 0;
return { repos: items, count: fetchCount, totalCount: resp.total_count || 0, actualCount: items.length };

const commits = $.steps.getCommits?.response || [];
return {
  fullName: $.loop.repo.full_name,
  recentCommits: (Array.isArray(commits) ? commits : []).slice(0, 5).map(c => ({
    sha: c.sha?.substring(0, 7) || '',
    message: (c.commit?.message || '').split('\n')[0].substring(0, 80),
    author: c.commit?.author?.name || c.author?.login || 'unknown',
    date: c.commit?.author?.date || ''
  }))
};

const repos = $.steps.checkResults.output.repos || [];
const commitIterations = $.steps.fetchDetails?.response?.iterations || [];

const commitMap = {};
commitIterations.forEach(iter => {
  const parsed = iter?.parseCommits?.output;
  if (parsed) commitMap[parsed.fullName] = parsed.recentCommits;
});

const result = repos.map(r => {
  const item = {
    fullName: r.full_name,
    description: (r.description || '').substring(0, 200),
    language: r.language,
    stars: r.stargazers_count || 0,
    forks: r.forks_count || 0,
    openIssues: r.open_issues_count || 0,
    topics: r.topics || [],
    isPrivate: r.private || false,
    defaultBranch: r.default_branch || 'main',
    updatedAt: r.updated_at,
    url: r.html_url
  };
  if (commitMap[r.full_name]) item.recentCommits = commitMap[r.full_name];
  return item;
});

return {
  repositories: result,
  totalFound: result.length,
  totalAvailable: $.steps.checkResults.output.totalCount,
  query: $.input.query,
  summary: 'Found ' + result.length + ' of ' + $.steps.checkResults.output.totalCount + ' repositories matching "' + $.input.query + '"'
};
